def lcs_length(a: str, b: str) -> int:
    # Use the shorter string for the DP row to reduce memory usage.
    if len(a) < len(b):
        a, b = b, a

    dp = [0] * (len(b) + 1)

    for char_a in a:
        previous_diagonal = 0
        for j, char_b in enumerate(b, 1):
            previous = dp[j]
            if char_a == char_b:
                dp[j] = previous_diagonal + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            previous_diagonal = previous

    return dp[-1]
